"use client";

import * as React from "react";
import { animate, motion, useMotionValue } from "motion/react";
import { cn } from "@/lib/utils";
import {
  signatureShapePaths,
  type SignatureShapeName,
} from "@/lib/cojeev/signature-shapes";
import {
  motionTokens,
  trackMotion,
  useChoreography,
} from "@/lib/cojeev-motion/choreography";
import { useMotionVisibility } from "@/lib/cojeev-motion/use-motion-visibility";
import { assignMotionRef } from "@/lib/cojeev-motion/refs";

export type ShapeArtworkTone = "pink" | "olive" | "blue" | "yellow";
export type ShapeArtworkOptions = {
  name?: SignatureShapeName;
  tone?: ShapeArtworkTone;
  /** Foreground rotation, in degrees. */
  rotation?: number;
  /** False draws the foreground as an outline. */
  filled?: boolean;
  shadow?: boolean;
  /** Direction of the cast shadow, clockwise from the right. */
  shadowAngle?: number;
  echo?: boolean;
  /** Rear outline rotation relative to the foreground. */
  echoAngle?: number;
  /** Omit when decorative. */
  label?: string;
  /** Opt-in ambient contour motion. It pauses offscreen and in quiet motion modes. */
  ambient?: boolean;
  /** Compatible signature silhouette used as the far end of the living contour. */
  morphTo?: SignatureShapeName;
  /** Full breathe cycle in seconds. */
  morphDuration?: number;
  /** Staggers compositions without relying on render-time randomness. */
  motionDelay?: number;
};
export type ShapeArtworkColors = { fill: string; shadow: string; echo: string };
export type ShapeArtworkProps = Omit<
  React.ComponentProps<"svg">,
  "name" | "children"
> &
  ShapeArtworkOptions;
const cycleDuration = (value: number | undefined) =>
  Number.isFinite(value) ? Math.max(4, Math.min(20, value!)) : 10;
const cycleDelay = (value: number | undefined) =>
  Number.isFinite(value) ? Math.max(0, Math.min(3, value!)) : 0;
const tones: Record<ShapeArtworkTone, string> = {
  pink: "#F0A4CC",
  olive: "#A8BC75",
  blue: "#95BAE8",
  yellow: "#F1D369",
};
const degrees = (value: number | undefined, fallback: number) => {
  const angle = Number.isFinite(value) ? (value as number) : fallback;
  return Number(((((angle % 360) + 540) % 360) - 180).toFixed(3));
};
const escapeXml = (value: string) =>
  value.replace(
    /[&<>"']/g,
    (character) =>
      ({
        "&": "&amp;",
        "<": "&lt;",
        ">": "&gt;",
        '"': "&quot;",
        "'": "&apos;",
      })[character]!,
  );

function artworkModel(options: ShapeArtworkOptions) {
  const name = options.name ?? "daisy-12";
  if (!Object.hasOwn(signatureShapePaths, name))
    throw new Error(`Unknown Cojeev signature shape: ${name}`);
  const tone = options.tone ?? "pink";
  if (!Object.hasOwn(tones, tone))
    throw new Error(`Unknown Cojeev artwork tone: ${tone}`);
  const rotation = degrees(options.rotation, 0);
  const shadowAngle = degrees(options.shadowAngle, 45);
  const echoAngle = degrees(options.echoAngle, -18);
  const filled = options.filled ?? true;
  const shadow = options.shadow ?? true;
  const echo = options.echo ?? true;
  const dx = Number((Math.cos((shadowAngle * Math.PI) / 180) * 9).toFixed(3));
  const dy = Number((Math.sin((shadowAngle * Math.PI) / 180) * 9).toFixed(3));
  const layers = [
    ...(shadow
      ? [
          {
            key: "shadow" as const,
            transform: `translate(${dx} ${dy}) rotate(${rotation} 50 50)`,
            filled,
            opacity: 0.18,
            width: 1.5,
          },
        ]
      : []),
    ...(echo
      ? [
          {
            key: "echo" as const,
            transform: `translate(9 -6) rotate(${degrees(rotation + echoAngle, 0)} 50 50)`,
            filled: false,
            opacity: 0.42,
            width: 0.85,
          },
        ]
      : []),
    {
      key: "fill" as const,
      transform: `rotate(${rotation} 50 50)`,
      filled,
      opacity: 1,
      width: 1.5,
    },
  ];
  return {
    name,
    tone,
    rotation,
    shadowAngle,
    echoAngle,
    filled,
    shadow,
    echo,
    label: options.label,
    path: signatureShapePaths[name],
    layers,
  };
}

/** Standalone vector artwork. Supply resolved colors to bake the current theme/palette. */
export function shapeArtworkSvg(
  options: ShapeArtworkOptions = {},
  colors?: Partial<ShapeArtworkColors>,
): string {
  const model = artworkModel(options);
  const paint: ShapeArtworkColors = {
    fill: colors?.fill ?? tones[model.tone],
    shadow: colors?.shadow ?? "#111111",
    echo: colors?.echo ?? "#14171B",
  };
  const semantics = model.label
    ? ` role="img" aria-label="${escapeXml(model.label)}"`
    : ' aria-hidden="true"';
  const layers = model.layers
    .map(
      (layer) =>
        `  <g data-artwork-layer="${layer.key}" transform="${layer.transform}" opacity="${layer.opacity}"><path d="${model.path}" fill="${layer.filled ? escapeXml(paint[layer.key]) : "none"}" stroke="${layer.filled ? "none" : escapeXml(paint[layer.key])}" stroke-width="${layer.width}" stroke-linejoin="round" /></g>`,
    )
    .join("\n");
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="-20 -20 140 140" width="512" height="512"${semantics}>\n${model.label ? `  <title>${escapeXml(model.label)}</title>\n` : ""}${layers}\n</svg>`;
}

/** All editable artwork state, as a copyable React usage example. */
export function shapeArtworkCode(options: ShapeArtworkOptions = {}): string {
  const model = artworkModel(options);
  const stringProp = (name: string, value: string) =>
    `  ${name}={${JSON.stringify(value)}}`;
  const motionProps = options.ambient
    ? [
        "  ambient={true}",
        ...(options.morphTo &&
        Object.hasOwn(signatureShapePaths, options.morphTo)
          ? [stringProp("morphTo", options.morphTo)]
          : []),
        `  morphDuration={${cycleDuration(options.morphDuration)}}`,
        `  motionDelay={${cycleDelay(options.motionDelay)}}`,
      ]
    : [];
  return [
    'import { ShapeArtwork } from "@/components/ui/shape-artwork";',
    "",
    "<ShapeArtwork",
    stringProp("name", model.name),
    stringProp("tone", model.tone),
    `  rotation={${model.rotation}}`,
    `  filled={${model.filled}}`,
    `  shadow={${model.shadow}}`,
    `  shadowAngle={${model.shadowAngle}}`,
    `  echo={${model.echo}}`,
    `  echoAngle={${model.echoAngle}}`,
    ...motionProps,
    ...(model.label ? [stringProp("label", model.label)] : []),
    '  style={{ width: "100%", maxWidth: 400 }}',
    "/>",
  ].join("\n");
}

/** One authored silhouette, shared by its face, cast shadow and rear outline. */
export function ShapeArtwork({
  name,
  tone,
  rotation,
  filled,
  shadow,
  shadowAngle,
  echo,
  echoAngle,
  label,
  ambient = false,
  morphTo,
  morphDuration = 10,
  motionDelay = 0,
  className,
  ref,
  ...props
}: ShapeArtworkProps) {
  const model = artworkModel({
    name,
    tone,
    rotation,
    filled,
    shadow,
    shadowAngle,
    echo,
    echoAngle,
    label,
  });
  const host = React.useRef<SVGSVGElement>(null);
  const hostRef = React.useCallback(
    (element: SVGSVGElement | null) => {
      host.current = element;
      return assignMotionRef(ref, element);
    },
    [ref],
  );
  const { quiet } = useChoreography();
  const { enabled, inView } = useMotionVisibility(host);
  const path = useMotionValue(model.path);
  const duration = cycleDuration(morphDuration);
  const delay = cycleDelay(motionDelay);
  React.useEffect(() => {
    const target =
      morphTo && Object.hasOwn(signatureShapePaths, morphTo)
        ? signatureShapePaths[morphTo]
        : model.path;
    if (quiet || !enabled || !inView || !ambient || target === model.path) {
      path.jump(model.path);
      return;
    }
    path.jump(model.path);
    return trackMotion(
      animate(path, [model.path, target, model.path], {
        duration,
        delay,
        ease: [...motionTokens.ease.settle],
        repeat: Infinity,
      }),
    );
  }, [
    ambient,
    model.path,
    duration,
    delay,
    morphTo,
    quiet,
    enabled,
    inView,
    path,
  ]);
  const paint: ShapeArtworkColors = {
    fill: `var(--v-${model.tone}, ${tones[model.tone]})`,
    shadow: "var(--ink-fixed, #111111)",
    echo: "var(--v-text, #14171B)",
  };
  return (
    <svg
      {...props}
      ref={hostRef}
      data-slot="shape-artwork"
      data-shape={model.name}
      data-morph-to={ambient ? morphTo : undefined}
      data-ambient={ambient || undefined}
      data-tone={model.tone}
      data-quiet={quiet || !enabled || !inView ? "true" : "false"}
      className={cn("v-shape-artwork", className)}
      viewBox="-20 -20 140 140"
      role={label ? "img" : undefined}
      aria-label={label}
      aria-hidden={label ? undefined : true}
      focusable="false"
    >
      {model.layers.map((layer) => (
        <g
          key={layer.key}
          data-artwork-layer={layer.key}
          transform={layer.transform}
          opacity={layer.opacity}
        >
          <motion.path
            d={path}
            fill={layer.filled ? paint[layer.key] : "none"}
            stroke={layer.filled ? "none" : paint[layer.key]}
            strokeWidth={layer.width}
            strokeLinejoin="round"
          />
        </g>
      ))}
    </svg>
  );
}

/** Original mathematical silhouettes inspired by the shared organic-shape moodboard.
 * Every path uses the same 96 cubic segments, so state changes can interpolate.
 */
type Point = readonly [number, number];
const tau = Math.PI * 2;
export function shapeContour(sample: (angle: number) => Point) {
  const points = Array.from({ length: 96 }, (_, i) => sample(i / 96 * tau));
  const f = (n: number) => Number(n.toFixed(3));
  let path = `M${f(points[0][0])} ${f(points[0][1])}`;
  for (let i = 0; i < points.length; i++) {
    const before = points[(i + 95) % 96], a = points[i], b = points[(i + 1) % 96], after = points[(i + 2) % 96];
    path += `C${f(a[0] + (b[0] - before[0]) / 6)} ${f(a[1] + (b[1] - before[1]) / 6)} ${f(b[0] - (after[0] - a[0]) / 6)} ${f(b[1] - (after[1] - a[1]) / 6)} ${f(b[0])} ${f(b[1])}`;
  }
  return path + "Z";
}
const radial = (radius: (angle: number) => number, sx = 1, sy = 1) => shapeContour(t => [50 + radius(t) * Math.cos(t) * sx, 50 + radius(t) * Math.sin(t) * sy]);
export const signatureShapePaths = {
  "daisy-12": radial(t => 35 + 10 * Math.cos(12 * t)),
  "petal-7": radial(t => 32 + 14 * Math.cos(7 * t)),
  "aster-9": radial(t => 29 + 16 * Math.pow((1 + Math.cos(9 * t)) / 2, 1.6)),
  "sunburst-24": radial(t => 39 + 7 * Math.cos(24 * t)),
  "clover-soft": radial(t => 35 + 10 * Math.cos(4 * t)),
  "cloud-3": radial(t => 37 + 7 * Math.cos(3 * t - .8), 1, .82),
  "pebble-soft": radial(t => 38 + 5 * Math.cos(3 * t + .6) + 2 * Math.sin(5 * t)),
  "pebble-tall": radial(t => 38 + 5 * Math.cos(3 * t + .2) + 2 * Math.sin(2 * t), .68, 1),
  "ribbon-soft": radial(t => 29 + 15 * Math.cos(2 * t) + 2 * Math.sin(5 * t), 1, .82),
  "scalloped-square": radial(t => (36 / Math.pow(Math.pow(Math.abs(Math.cos(t)), 6) + Math.pow(Math.abs(Math.sin(t)), 6), 1 / 6)) + 2.2 * Math.cos(16 * t)),
  "cushion": radial(t => 37 - 5 * Math.cos(4 * t) + 1.5 * Math.cos(8 * t)),
  "seed-wing": radial(t => 34 + 8 * Math.cos(3 * t) + 4 * Math.sin(2 * t)),
} as const;
export type SignatureShapeName = keyof typeof signatureShapePaths;

"use client";

import * as React from "react";
import { animate, frameSteps, motionValue, type AnimationPlaybackControls, type Transition } from "motion";
import { getMotionTime, isMotionClockFrozen, registerMotionClock } from "@/lib/cojeev-motion/clock";
import { getSettingsSnapshot, getServerSettingsSnapshot, subscribeSettings, type SettingsSnapshot } from "@/lib/cojeev-motion/settings";
import { useReducedMotion } from "@/lib/cojeev-motion/use-reduced-motion";

/** The shared rhythm. Durations and stagger are seconds, matching Motion's API. */
export const motionTokens = {
  spring: {
    responsive: { type: "spring", stiffness: 360, damping: 32, mass: .85 },
    expressive: { type: "spring", stiffness: 260, damping: 22, mass: 1 },
    gentle: { type: "spring", stiffness: 180, damping: 28, mass: 1 },
  },
  ease: { enter: [.2, .8, .2, 1], exit: [.4, 0, 1, 1], settle: [.2, .65, .25, 1] },
  duration: { quick: .16, enter: .32, exit: .18 },
  stagger: .035,
} as const;

export function resolveChoreography(snapshot: SettingsSnapshot, reduced: boolean): { quiet: boolean; transition: Transition } {
  const quiet = reduced || snapshot.motion.mode === "off" || snapshot.flow.variant === "off";
  if (quiet) return { quiet, transition: { duration: 0, delay: 0 } };
  const speed = snapshot.flow.speed;
  const spring = ["jelly", "rubber", "drop", "pebble"].includes(snapshot.flow.variant)
    ? motionTokens.spring.expressive : motionTokens.spring.responsive;
  return { quiet, transition: { ...spring, stiffness: spring.stiffness * speed * speed, damping: spring.damping * speed } };
}

/** Reactive settings subscription for reusable React surfaces. */
export function useChoreography() {
  const snapshot = React.useSyncExternalStore(subscribeSettings, getSettingsSnapshot, getServerSettingsSnapshot);
  const reduced = useReducedMotion();
  return React.useMemo(() => resolveChoreography(snapshot, reduced), [snapshot, reduced]);
}

/** Connect Motion's JS animations to the existing deterministic document clock. */
export function trackMotion(controls: AnimationPlaybackControls) {
  let origin = getMotionTime() - controls.time * 1000;
  let frozen = isMotionClockFrozen();
  if (frozen) controls.pause();
  const release = registerMotionClock(time => {
    if (time === null) {
      if (frozen) controls.play();
      frozen = false;
      return;
    }
    if (!frozen) {
      origin = time - controls.time * 1000;
      controls.pause();
      frozen = true;
    }
    controls.time = Math.max(0, time - origin) / 1000;
    if (controls.time >= controls.duration) controls.complete();
    // A seek schedules Motion's update phase. Flush it at this explicit sample;
    // normal playback stays entirely on Motion's own animation frame loop.
    frameSteps.update.process({ delta: 0, timestamp: performance.now(), isProcessing: false });
  });
  void controls.finished.then(release, release);
  return () => { release(); controls.stop(); };
}

/** One interruptible spring per scalar; retargets inherit the current value and velocity. */
export function createMotionLane(initial: number, render: (value: number) => void) {
  const value = motionValue(initial);
  const unsubscribe = value.on("change", render);
  let cancel = () => {};
  let generation = 0;
  const stop = () => { generation++; cancel(); cancel = () => {}; value.stop(); };
  const jump = (target: number) => { stop(); value.jump(target); render(target); };
  return {
    get: () => value.get(),
    jump,
    to(target: number, transition: Transition, complete?: () => void) {
      stop();
      if (transition.duration === 0) { jump(target); complete?.(); return; }
      const owner = generation;
      const controls = animate(value, target, {
        ...transition,
        autoplay: !isMotionClockFrozen(),
        onComplete: () => { if (generation === owner) complete?.(); },
      });
      cancel = trackMotion(controls);
    },
    stop,
    dispose: () => { stop(); unsubscribe(); value.destroy(); },
  };
}

/** One document-time clock for springs, cancellable phase timers, then Web Animations. */
export type MotionTimer = {at:number;run:()=>void;native:ReturnType<typeof setTimeout>|null;cancelled:boolean}
let time:number|null=null
const pending=new Set<MotionTimer>()
const drivers=new Set<(time:number|null)=>void>()
const animationStarts=new Map<Animation,{at:number;wasRunning:boolean}>()
const now=()=>time??performance.now()
function arm(timer:MotionTimer){timer.native=setTimeout(()=>{timer.native=null;if(timer.cancelled)return;pending.delete(timer);timer.run()},Math.max(0,timer.at-performance.now()))}
export function scheduleMotion(run:()=>void,delay:number):MotionTimer{
 const timer:MotionTimer={at:now()+Math.max(0,delay),run,native:null,cancelled:false};pending.add(timer)
 if(time===null)arm(timer)
 return timer
}
export function cancelMotion(timer:MotionTimer|null|undefined){if(!timer)return;timer.cancelled=true;if(timer.native!==null)clearTimeout(timer.native);timer.native=null;pending.delete(timer)}
export function registerMotionClock(driver:(time:number|null)=>void){drivers.add(driver);return ()=>{drivers.delete(driver)}}
export function getMotionTime(){return now()}
export function isMotionClockFrozen(){return time!==null}
/** Freeze before an interaction. First spring delta is zero; timer callbacks can enqueue subsequent beats. */
export function motionClock(next:number|null){
 if(next===null){
  const was=time;time=null
  if(was!==null)for(const timer of pending){timer.at=performance.now()+Math.max(0,timer.at-was);arm(timer)}
  drivers.forEach(driver=>driver(null))
  for(const [animation,state] of animationStarts){if(state.wasRunning)animation.play()}
  animationStarts.clear();return
 }
 if(!Number.isFinite(next))throw new Error("Motion clock expects finite milliseconds or null.")
 if(time===null){const real=performance.now();for(const timer of pending){if(timer.native!==null)clearTimeout(timer.native);timer.native=null;timer.at=next+Math.max(0,timer.at-real)}}
 time=next
 drivers.forEach(driver=>driver(next))
 // Due callbacks observe this clock sample, matching the source phase queue.
 let due:MotionTimer|undefined
 while((due=[...pending].filter(timer=>timer.at<=next).sort((a,b)=>a.at-b.at)[0])){
  pending.delete(due);if(due.cancelled)continue;due.run()
 }
 time=next
 if(typeof document!=="undefined"){
  const animations=document.getAnimations()
  for(const animation of animations){
   if(!animationStarts.has(animation)){animationStarts.set(animation,{at:next,wasRunning:animation.playState==="running"});animation.pause()}
   animation.currentTime=Math.max(0,next-animationStarts.get(animation)!.at)
  }
  for(const animation of animationStarts.keys())if(!animations.includes(animation))animationStarts.delete(animation)
 }
}
export const flowClock=motionClock

export const RUNTIME={cfg:{rest:false,reach:true,merge:true,hold:true,jiggleOn:true,press:true,echo:false,dots:0,grain:.08,sheen:.6,curve:1.2,lobeK:130,lobeZ:1,mergeZ:.8,arcK:40,holdK:80,pressK:170,jiggle:.35,jiggleDecay:1.6,restSpeed:1,drift:1,quality:2.5},
 tier:{pill:{amp:0,reach:3,inside:1.2,press:.02},tile:{amp:0,reach:2.4,inside:1,press:.02},nav:{amp:0,reach:1.2,inside:.5,press:.008},card:{amp:0,reach:1,inside:.4,press:.004},blob:{amp:.006,reach:3,inside:1.2,press:.03}}};
/* Per-tier authoring domains live with the profile, so a slider cannot offer a value the tier cannot mean
