@layer cojeev-states {
.v-shape-artwork {
  display: block;
  width: 100%;
  height: auto;
  aspect-ratio: 1;
  overflow: visible;
  flex-shrink: 0;
}
.v-shape-artwork > g {
  pointer-events: none;
}

/* Shared by the studio's live and copied examples. */
.v-shape-studio {
  width: 100%;
  min-width: 0;
  padding: 18px;
  container-type: inline-size;
  display: grid;
  gap: 24px;
  color: var(--v-text);
}
.v-shape-studio__heading {
  max-width: 440px;
}
.v-shape-studio__eyebrow {
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--v-muted);
}
.v-shape-studio__heading h3 {
  font-size: clamp(24px, 5cqi, 34px);
  line-height: 1.12;
  font-weight: 550;
  margin: 14px 0;
  letter-spacing: -0.025em;
}
.v-shape-studio__heading > p:last-child {
  font-size: 14px;
  color: var(--v-muted);
  line-height: 1.6;
}
.v-shape-studio__desk {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  border: 1px solid var(--v-border);
  border-radius: 28px;
  background: var(--v-paper);
}
.v-shape-studio__proof {
  position: relative;
  min-width: 0;
  display: grid;
  justify-items: center;
  align-content: center;
  padding: 24px;
  border-radius: 28px 28px 0 0;
  background:
    radial-gradient(
      ellipse at 38% 35%,
      color-mix(in srgb, var(--v-yellow) 15%, transparent),
      transparent 70%
    ),
    var(--v-paper);
}
.v-shape-studio__registration {
  position: absolute;
  left: 18px;
  top: 12px;
  font-size: 20px;
  color: var(--v-muted);
  opacity: 0.5;
  pointer-events: none;
}
.v-shape-studio__art {
  width: 100%;
  max-width: 330px;
}
.v-shape-studio__caption {
  display: flex;
  gap: 14px;
  align-items: baseline;
  margin: 10px 0 18px;
  font-size: 16px;
}
.v-shape-studio__caption small {
  color: var(--v-muted);
  font-size: 11px;
}
.v-shape-studio__controls {
  min-width: 0;
  display: grid;
  gap: 24px;
  padding: 24px;
  border-top: 1px solid var(--v-border);
}
.v-shape-studio__label,
.v-shape-studio__layers legend {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.035em;
  margin: 0 0 12px;
}
.v-shape-studio__tones {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 4px;
}
.v-shape-studio__tones > button {
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-width: 44px;
  min-height: 64px;
  padding: 8px 0;
}
.v-shape-studio__tones > button > span:not([data-slot]) {
  width: 18px;
  height: 18px;
  border: 1px solid var(--v-border);
  border-radius: 50%;
}
.v-shape-studio__tones small {
  text-transform: capitalize;
  font-size: 11px;
}
.v-shape-studio__tones > button[aria-pressed="true"] > span:not([data-slot]) {
  outline: 2px solid var(--v-text);
  outline-offset: 4px;
}
.v-shape-studio__tones > button[aria-pressed="true"] {
  background: var(--v-accent-soft);
}
.v-shape-studio__layers {
  border: 0;
  padding: 0;
  margin: 0;
  min-width: 0;
}
.v-shape-studio__layers > div {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  min-height: 44px;
}
.v-shape-studio__layers > div + div {
  margin-top: 10px;
}
.v-shape-studio__motion {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}
.v-shape-studio__hint {
  font-size: 12px;
  line-height: 1.6;
  color: var(--v-muted);
  margin: 12px 0;
}
.v-shape-studio__tray {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}
.v-shape-studio__tray > button,
.v-shape-studio__masks > button {
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 16px 6px;
  min-width: 0;
  min-height: 94px;
  border-radius: 16px;
}
.v-shape-studio__tray small,
.v-shape-studio__masks small {
  font-size: 11px;
  overflow-wrap: anywhere;
  line-height: 1.4;
}
.v-shape-studio__tray > button[aria-pressed="true"] {
  background: var(--v-accent-soft);
  box-shadow: inset 0 0 0 1px var(--v-accent-ink);
}
.v-shape-studio__details {
  display: grid;
  gap: 24px;
  padding: 18px 12px 24px;
}
.v-shape-studio__range > div {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 12px;
}
.v-shape-studio__range output {
  font-size: 12px;
  color: var(--v-muted);
  font-variant-numeric: tabular-nums;
}
.v-shape-studio__export {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 20px;
  padding-top: 10px;
}
.v-shape-studio__export h4 {
  font-size: 18px;
  font-weight: 550;
  margin: 0 0 8px;
}
.v-shape-studio__export p,
.v-shape-studio__receipt {
  font-size: 12px;
  line-height: 1.6;
  color: var(--v-muted);
}
.v-shape-studio__receipt {
  min-height: 38px;
}
.v-shape-studio__inventory {
  --h: 360px;
}
.v-shape-studio__masks {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(80px, 1fr));
  gap: 12px;
  padding: 16px;
}
@container (min-width:550px) {
  .v-shape-studio__desk {
    grid-template-columns: minmax(0, 1fr) minmax(250px, 0.8fr);
  }
  .v-shape-studio__proof {
    border-radius: 28px 0 0 28px;
  }
  .v-shape-studio__controls {
    border-top: 0;
    border-left: 1px solid var(--v-border);
  }
  .v-shape-studio__tray {
    grid-template-columns: repeat(6, minmax(0, 1fr));
  }
  .v-shape-studio__details {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

}
